style.css:
/* Change background from black to your preferred color */
body, html {
  background-color: #f5f0e8 !important;  /* warm off-white */
  color: #222222 !important;              /* dark gray text */
}

/* Catch any other black backgrounds */
* {
  background-color: inherit;
}

div, section, main, header, footer, nav {
  background-color: transparent !important;
}
